const data = $input.first().json;
const posts = data?.data?.children || [];
const topPosts = posts
  .filter(p => !p.data.stickied)
  .slice(0, 10)
  .map((p, i) => {
    const d = p.data;
    return `${i+1}. [Score: ${d.score}] ${d.title} (${d.num_comments} comments)`;
  })
  .join('\n');
return { json: { redditSummary: topPosts } };

const redditRaw = $('Fetch Reddit Posts').first().json;
const redditPosts = (redditRaw?.data?.children || []).filter(p => !p.data.stickied);
const hnRaw = $input.first().json;
const hnHits = hnRaw.hits || [];
const fs = require('fs');

const VIRAL_KEYWORDS = ['ai ', ' ai', 'robot', 'ban', 'billion', 'trillion', 'hack', 'breach', 'leak', 'secret', 'first ', 'outrage', 'lawsuit', 'fired', 'ceo ', 'agi', 'gpt', 'claude', 'open source', 'shutdown', 'censor', 'record ', 'largest', 'biggest', 'collapse', 'surge', 'revolution', 'milestone', 'breakthrough'];

function viralBoost(title) {
  const lower = title.toLowerCase();
  return VIRAL_KEYWORDS.filter(k => lower.includes(k)).length * 300;
}

const scored = [
  ...redditPosts.map(p => ({
    source: 'Reddit',
    title: p.data.title,
    engagementScore: p.data.score + p.data.num_comments * 2 + viralBoost(p.data.title)
  })),
  ...hnHits.slice(0, 10).map(h => ({
    source: 'HN',
    title: h.title,
    engagementScore: h.points + h.num_comments * 3 + viralBoost(h.title)
  }))
].sort((a, b) => b.engagementScore - a.engagementScore);

// 14-day duplicate detection (60% word-overlap check)
const historyPath = '/home/node/videos/last_stories.json';
let history = [];
try {
  const cutoff = Date.now() - 14 * 24 * 60 * 60 * 1000;
  history = JSON.parse(fs.readFileSync(historyPath, 'utf8')).filter(h => h.ts > cutoff);
} catch(e) {}

function significantWords(title) {
  return title.toLowerCase().split(/\s+/).filter(w => w.length >= 4);
}
function isDuplicate(title) {
  const words = new Set(significantWords(title));
  if (words.size === 0) return false;
  for (const h of history) {
    const hWords = new Set(significantWords(h.title));
    const overlap = [...words].filter(w => hWords.has(w)).length;
    if (overlap / words.size >= 0.6) return true;
  }
  return false;
}

const filtered = scored.filter(s => !isDuplicate(s.title));
const top3 = (filtered.length >= 3 ? filtered : scored).slice(0, 3);

// Save chosen story to history
const chosen = top3[0];
history.push({ title: chosen.title, ts: Date.now() });
try {
  fs.mkdirSync('/home/node/videos', { recursive: true });
  fs.writeFileSync(historyPath, JSON.stringify(history));
} catch(e) {}

const rankedStories = top3.map((s, i) =>
  `${i+1}. [${s.source} | Score: ${s.engagementScore}] ${s.title}`
).join('\n');

return { json: { rankedStories } };

const data = $input.first().json;
return {
  json: {
    rawStory: data.rankedStories,
    timestamp: new Date().toISOString()
  }
};

const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const storyData = $input.first().json;
const rawStory = storyData.rawStory;
if (!rawStory) throw new Error('No rawStory from Prepare Story Data');

const keys = JSON.parse(fs.readFileSync('/home/node/keys.json', 'utf8'));
const geminiApiKey = keys.geminiApiKey;
if (!geminiApiKey || geminiApiKey === 'YOUR_GEMINI_API_KEY') throw new Error('geminiApiKey not set in keys.json');

const systemPrompt = `You are a YouTube Shorts scriptwriter creating viral tech news content in the HECK format (Hook-Explain-Climax-Kicker).

HECK STRUCTURE — write exactly 6 complete sentences:
1. Hook: Shocking stat or question that grabs attention (5-8 words).
2. Explain beat 1: What happened. Tied to a distinct visual.
3. Explain beat 2: Why it matters. Tied to a distinct visual.
4. Climax beat 1: The twist, consequence, or scale revelation. Tied to a visual.
5. Climax beat 2: The deeper implication. Tied to a visual.
6. Kicker: A SELF-CONTAINED complete sentence that resonates thematically with the Hook.

HARD RULES (non-negotiable — violating these breaks the pipeline):
- The SCRIPT must be exactly 6 complete sentences.
- Every sentence — including the Kicker — MUST end with a period, question mark, or exclamation mark.
- The very last character of the SCRIPT string MUST be . or ! or ? — no exceptions.
- No sentence may end in a conjunction (and, or, but, because, that, while, as), a preposition (of, to, in, on, for, with, by), an article (a, an, the), or a comma.
- The replay loop is THEMATIC, not grammatical. Do NOT write a Kicker that syntactically trails off into the Hook. The Kicker must stand alone as a finished thought.
- No filler phrases: "in conclusion", "stay tuned", "let me know", "subscribe".
- Each sentence completable in one breath.

SOFT TARGET:
- Aim for 75-95 words total. Sentence completeness always beats hitting the word count — if you're at 95 words and the Kicker isn't closed, finish it.

BAD Kicker examples (NEVER do this):
- "It seems the biggest tech giants are finally realizing that" (trails off, ends in conjunction)
- "And history is once again rewritten before" (trails off, ends in preposition)
- "The only question now is" (ends in verb, no object, no punctuation)

GOOD Kicker examples:
- "The age of untouchable monopolies is finally ending."
- "Maybe this time, the giants really do fall."
- "What seemed impossible yesterday is inevitable today."

SELF-CHECK BEFORE OUTPUT: Read your SCRIPT string's last 3 characters. They must end in a letter followed by . ! or ?. If not, rewrite the final sentence.

OUTPUT (strict JSON, no markdown):
{
  "SCRIPT": "Hook sentence. Explain1. Explain2. Climax1. Climax2. Kicker.",
  "TITLE": "YouTube title under 100 chars, no #Shorts",
  "DESCRIPTION": "2-3 sentence context description",
  "TAGS": ["tag1","tag2","tag3","tag4","tag5","tag6"],
  "IMAGE_PROMPTS": [
    "Hook visual: ...",
    "Explain beat 1: ...",
    "Explain beat 2: ...",
    "Climax beat 1: ...",
    "Climax beat 2: ...",
    "Kicker visual: ..."
  ]
}`;

const tmpDir = '/tmp/n8n_gemini_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  const config = { geminiApiKey, rawStory, systemPrompt };
  fs.writeFileSync(path.join(tmpDir, 'cfg.json'), JSON.stringify(config));

  const js = [
    "const https = require('https');",
    "const fs = require('fs');",
    "const cfg = JSON.parse(fs.readFileSync(process.argv[2]+'/cfg.json','utf8'));",
    "const {geminiApiKey, rawStory, systemPrompt} = cfg;",
    "const body = JSON.stringify({",
    "  system_instruction:{parts:[{text:systemPrompt}]},",
    "  contents:[{role:'user',parts:[{text:rawStory}]}],",
    "  generationConfig:{responseMimeType:'application/json',maxOutputTokens:8192,thinkingConfig:{thinkingBudget:0}}",
    "});",
    "const req = https.request({hostname:'generativelanguage.googleapis.com',path:'/v1beta/models/gemini-3-flash-preview:generateContent?key='+geminiApiKey,method:'POST',headers:{'Content-Type':'application/json','Content-Length':Buffer.byteLength(body)}}, res => {",
    "  const c=[]; res.on('data',d=>c.push(d)); res.on('end',()=>{",
    "    if (res.statusCode!==200){process.stderr.write('FATAL: Gemini '+res.statusCode+': '+Buffer.concat(c).toString().substring(0,500)+'\\n');process.exit(1);return;}",
    "    process.stdout.write(Buffer.concat(c).toString());",
    "  });",
    "});",
    "req.on('error',e=>{process.stderr.write('FATAL: '+e.message+'\\n');process.exit(1);});",
    "req.write(body); req.end();"
  ].join('\n');
  fs.writeFileSync(path.join(tmpDir, 'run.js'), js);

  const out = await new Promise((resolve, reject) => {
    exec('node "' + path.join(tmpDir, 'run.js') + '" "' + tmpDir + '"',
      { timeout: 60000, maxBuffer: 5*1024*1024 },
      (err, stdout, stderr) => {
        if (err) { const fm=(stderr||'').match(/FATAL: ([\s\S]+)/); reject(new Error(fm?fm[1].trim():stderr||err.message)); }
        else resolve(stdout);
      });
  });

  const raw = JSON.parse(out);

  // Sentence-completeness validation: if Gemini returns a script that doesn't end with
  // terminal punctuation, throw so n8n retries (retryOnFail: true, maxTries: 3).
  // parseScript has a final safety-net truncation if all 3 retries still fail.
  try {
    const text = raw.candidates[0].content.parts[0].text;
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const data = JSON.parse(jsonMatch[0]);
      const findScriptData = o => {
        if (!o || typeof o !== 'object') return null;
        if (o.SCRIPT || o.script) return o;
        for (const k of Object.keys(o)) {
          const v = o[k];
          if (v && typeof v === 'object' && !Array.isArray(v) && (v.SCRIPT || v.script)) return v;
        }
        return null;
      };
      const sData = findScriptData(data);
      const script = sData ? (sData.SCRIPT || sData.script || '') : '';
      if (script && !/[.!?]["')\]]?\s*$/.test(script.trim())) {
        throw new Error('Script ends mid-sentence (last 40 chars: "' + script.trim().slice(-40) + '"). n8n will retry.');
      }
    }
  } catch(e) {
    if (/mid-sentence/.test(e.message)) throw e;
    // Other parse errors — let parseScript handle them for better error context
  }

  return { json: raw };
} finally {
  try { fs.rmSync(tmpDir, {recursive:true, force:true}); } catch(e) {}
}

const geminiResponse = $input.first().json;
let response = '';
try {
  response = geminiResponse.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Could not extract text from Gemini response: ' + JSON.stringify(geminiResponse).substring(0, 300));
}
let parsed;
try {
  parsed = JSON.parse(response);
} catch (e) {
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) { parsed = JSON.parse(jsonMatch[0]); }
  else throw new Error('Could not parse script JSON: ' + response.substring(0, 200));
}
function findScriptData(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj.SCRIPT || obj.script) return obj;
  for (const key of Object.keys(obj)) {
    const val = obj[key];
    if (val && typeof val === 'object' && !Array.isArray(val)) {
      if (val.SCRIPT || val.script) return val;
    }
  }
  return null;
}
let data = findScriptData(parsed);
if (!data) throw new Error('Could not find SCRIPT in response. Keys: ' + JSON.stringify(Object.keys(parsed)));
let script = data.SCRIPT || data.script;
const title = data.TITLE || data.title;
const description = data.DESCRIPTION || data.description || '';
const tags = data.TAGS || data.tags || [];
const imagePrompts = data.IMAGE_PROMPTS || data.image_prompts || data.imagePrompts || [];
if (!script) throw new Error('SCRIPT field is empty');
if (!title) throw new Error('TITLE field is empty');
if (!Array.isArray(imagePrompts) || imagePrompts.length < 5) {
  throw new Error('Need at least 5 image prompts, got ' + (Array.isArray(imagePrompts) ? imagePrompts.length : 'non-array'));
}

// Safety-net truncation: if script still ends mid-sentence after all scriptGen retries,
// truncate to the last complete sentence so voiceover never cuts off mid-word.
script = script.trim();
if (!/[.!?]["')\]]?$/.test(script)) {
  const matches = [...script.matchAll(/[.!?]["')\]]?(?=\s|$)/g)];
  if (matches.length > 0) {
    const last = matches[matches.length - 1];
    const truncated = script.substring(0, last.index + last[0].length).trim();
    console.log('Script truncated to last complete sentence (was ' + script.length + ' chars, now ' + truncated.length + ' chars)');
    script = truncated;
  } else {
    throw new Error('Script has no terminal punctuation anywhere: ' + script.substring(0, 120));
  }
}

const wordCount = script.split(/\s+/).filter(Boolean).length;
if (wordCount < 65) {
  throw new Error('Script too short after truncation: ' + wordCount + ' words (need 65+). Original ended mid-sentence and truncation left too little.');
}
if (!Array.isArray(tags) || tags.length < 3) {
  throw new Error('Need at least 3 tags, got ' + (Array.isArray(tags) ? tags.length : 'non-array'));
}
return {
  json: {
    script,
    title,
    description,
    tags: Array.isArray(tags) ? tags : [],
    imagePrompts,
    wordCount,
    timestamp: new Date().toISOString()
  }
};

const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const scriptData = $input.first().json;
const prompts = scriptData.imagePrompts || [];
if (prompts.length === 0) throw new Error('No image prompts found');

const keys = JSON.parse(fs.readFileSync('/home/node/keys.json', 'utf8'));
const falApiKey = keys.falApiKey;
const stabilityApiKey = keys.stabilityApiKey;
if (!falApiKey || falApiKey === 'YOUR_FAL_API_KEY') throw new Error('falApiKey not set in keys.json');

const tmpDir = '/tmp/n8n_imgs_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  // Atomic provider selection: check Stability AI balance first
  let useSD3 = false;
  if (stabilityApiKey && stabilityApiKey !== 'YOUR_STABILITY_API_KEY') {
    try {
      const { execSync } = require('child_process');
      const balCfg = { stabilityApiKey };
      fs.writeFileSync(path.join(tmpDir, 'bal_cfg.json'), JSON.stringify(balCfg));
      const balJs = [
        "const https = require('https');",
        "const fs = require('fs');",
        "const cfg = JSON.parse(fs.readFileSync(process.argv[2]+'/bal_cfg.json','utf8'));",
        "const req = https.request({hostname:'api.stability.ai',path:'/v1/user/balance',method:'GET',headers:{'Authorization':'Bearer '+cfg.stabilityApiKey,'Accept':'application/json'}}, res => {",
        "  const c=[]; res.on('data',d=>c.push(d)); res.on('end',()=>process.stdout.write(Buffer.concat(c).toString()));",
        "});",
        "req.on('error',()=>process.stdout.write('{\"credits\":0}'));",
        "req.end();"
      ].join('\n');
      fs.writeFileSync(path.join(tmpDir, 'bal.js'), balJs);
      const balOut = execSync('node "' + path.join(tmpDir, 'bal.js') + '" "' + tmpDir + '"', { timeout: 10000 }).toString();
      const bal = JSON.parse(balOut);
      const needed = prompts.length * 13;
      if ((bal.credits || 0) >= needed) {
        useSD3 = true;
      } else {
        process.stderr.write('SD3 balance ' + (bal.credits||0).toFixed(0) + ' < needed ' + needed + ', using fal.ai Flux\n');
      }
    } catch(e) { process.stderr.write('Balance check failed (' + e.message + '), using fal.ai Flux\n'); }
  }

  const config = { prompts, falApiKey, stabilityApiKey, useSD3 };
  fs.writeFileSync(path.join(tmpDir, 'cfg.json'), JSON.stringify(config));

  const js = [
    "const https = require('https');",
    "const fs = require('fs');",
    "const cfg = JSON.parse(fs.readFileSync(process.argv[2]+'/cfg.json','utf8'));",
    "const {prompts, falApiKey, stabilityApiKey, useSD3} = cfg;",
    "",
    "function postJson(hostname, urlPath, body, headers) {",
    "  return new Promise((res, rej) => {",
    "    const b = JSON.stringify(body);",
    "    const r = https.request({hostname, path:urlPath, method:'POST', headers:{...headers,'Content-Type':'application/json','Content-Length':Buffer.byteLength(b)}}, resp => {",
    "      const c=[]; resp.on('data',d=>c.push(d)); resp.on('end',()=>res({s:resp.statusCode,b:Buffer.concat(c).toString()}));",
    "    });",
    "    r.on('error',rej); r.write(b); r.end();",
    "  });",
    "}",
    "",
    "function postMultipart(hostname, urlPath, boundary, bodyBuf, headers) {",
    "  return new Promise((res, rej) => {",
    "    const r = https.request({hostname, path:urlPath, method:'POST', headers:{...headers,'Content-Type':'multipart/form-data; boundary='+boundary,'Content-Length':bodyBuf.length}}, resp => {",
    "      const c=[]; resp.on('data',d=>c.push(d)); resp.on('end',()=>res({s:resp.statusCode,b:Buffer.concat(c).toString()}));",
    "    });",
    "    r.on('error',rej); r.write(bodyBuf); r.end();",
    "  });",
    "}",
    "",
    "async function genSD3(prompt) {",
    "  const boundary = '----n8nbnd'+Date.now();",
    "  const parts = [",
    "    '--'+boundary+'\\r\\nContent-Disposition: form-data; name=\"prompt\"\\r\\n\\r\\n'+'cinematic portrait 9:16 vertical, '+prompt,",
    "    '--'+boundary+'\\r\\nContent-Disposition: form-data; name=\"aspect_ratio\"\\r\\n\\r\\n9:16',",
    "    '--'+boundary+'\\r\\nContent-Disposition: form-data; name=\"output_format\"\\r\\n\\r\\njpeg',",
    "    '--'+boundary+'--'",
    "  ].join('\\r\\n');",
    "  const r = await postMultipart('api.stability.ai','/v2beta/stable-image/generate/sd3',boundary,Buffer.from(parts),{'Authorization':'Bearer '+stabilityApiKey,'Accept':'application/json'});",
    "  if (r.s !== 200) throw new Error('SD3 '+r.s+': '+r.b.substring(0,300));",
    "  const data = JSON.parse(r.b);",
    "  return 'data:image/jpeg;base64,'+data.image;",
    "}",
    "",
    "async function genFlux(prompt) {",
    "  const r = await postJson('fal.run','/fal-ai/flux/schnell',{prompt:'cinematic portrait 9:16 vertical composition, '+prompt,image_size:{width:768,height:1344},num_images:1,enable_safety_checker:false},{'Authorization':'Key '+falApiKey});",
    "  if (r.s !== 200) throw new Error('Flux '+r.s+': '+r.b.substring(0,300));",
    "  return JSON.parse(r.b).images[0].url;",
    "}",
    "",
    "async function main() {",
    "  const imageUrls = [];",
    "  const provider = useSD3 ? 'sd3' : 'flux';",
    "  process.stderr.write('Provider: '+provider+'\\n');",
    "  for (let i=0; i<prompts.length; i++) {",
    "    process.stderr.write('Image '+(i+1)+'/'+prompts.length+'\\n');",
    "    const url = useSD3 ? await genSD3(prompts[i]) : await genFlux(prompts[i]);",
    "    imageUrls.push(url);",
    "    process.stderr.write('  OK\\n');",
    "  }",
    "  process.stdout.write(JSON.stringify({imageUrls, provider}));",
    "}",
    "main().catch(e=>{process.stderr.write('FATAL: '+e.message+'\\n');process.exit(1);});"
  ].join('\n');
  fs.writeFileSync(path.join(tmpDir, 'run.js'), js);

  const out = await new Promise((resolve, reject) => {
    exec('node "' + path.join(tmpDir, 'run.js') + '" "' + tmpDir + '"',
      { timeout: 300000, maxBuffer: 10*1024*1024 },
      (err, stdout, stderr) => {
        if (err) { const fm=(stderr||'').match(/FATAL: ([\s\S]+)/); reject(new Error(fm?fm[1].trim():stderr||err.message)); }
        else resolve(stdout);
      });
  });

  const result = JSON.parse(out);
  return {
    json: {
      imageUrls: result.imageUrls,
      imageCount: result.imageUrls.length,
      imageProvider: result.provider,
      script: scriptData.script,
      title: scriptData.title,
      description: scriptData.description,
      tags: scriptData.tags,
      imagePrompts: scriptData.imagePrompts
    }
  };
} finally {
  try { fs.rmSync(tmpDir, {recursive:true, force:true}); } catch(e) {}
}

