const fs = require('fs');
const path = require('path');

const videoData = $input.first().json;
const script = $('Parse Script JSON').first().json.script || videoData.script;
if (!script) throw new Error('No script text found');

const keys = JSON.parse(fs.readFileSync('/home/node/keys.json', 'utf8'));
const apiKey = keys.elevenLabsApiKey;
if (!apiKey || apiKey === 'YOUR_ELEVENLABS_API_KEY') throw new Error('elevenLabsApiKey not set in keys.json');

const tmpDir = '/tmp/n8n_tts_' + Date.now();
