    "  headers: {'Content-Type':'application/json','Content-Length':Buffer.byteLength(body),'xi-api-key':apiKey}",
    "}, res => {",
    "  if (res.statusCode !== 200) {",
    "    const c=[]; res.on('data',d=>c.push(d)); res.on('end',()=>{process.stderr.write('FATAL: ElevenLabs error '+res.statusCode+': '+Buffer.concat(c).toString().substring(0,300)+'\\n'); process.exit(1);});",
    "    return;",
    "  }",
    "  const outPath = process.argv[2]+'/voice.mp3';",
    "  const out = require('fs').createWriteStream(outPath);",
    "  res.pipe(out);",
    "  out.on('finish', () => { process.stdout.write(JSON.stringify({ok:true})); });",
    "  out.on('error', e => { process.stderr.write('FATAL: '+e.message+'\\n'); process.exit(1); });",
    "});",
    "req.on('error', e=>{ process.stderr.write('FATAL: '+e.message+'\\n'); process.exit(1); });",
    "req.write(body); req.end();"
  ];
  fs.writeFileSync(path.join(tmpDir, 'tts.js'), js.join('\n'));

  await new Promise((resolve, reject) => {
    exec('node "' + path.join(tmpDir, 'tts.js') + '" "' + tmpDir + '"',
      { timeout: 60000, maxBuffer: 50*1024*1024 },
      (err, stdout, stderr) => {
        if (err) { const fm=(stderr||'').match(/FATAL: ([\s\S]+)/); reject(new Error(fm?fm[1].trim():stderr||err.message)); }
        else resolve();
      });
  });

  const audioBuffer = fs.readFileSync(path.join(tmpDir, 'voice.mp3'));
  return {
    json: { ...videoData, voiceGenerated: true },
    binary: {
      voice: {
        data: audioBuffer.toString('base64'),
        mimeType: 'audio/mpeg',
        fileName: 'voiceover.mp3'
      }
    }
  };
} finally {
  try { fs.rmSync(tmpDir, {recursive:true, force:true}); } catch(e) {}
}

const { exec, execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const inputItem = $input.first();
const voiceBinary = inputItem.binary && inputItem.binary.voice;
if (!voiceBinary) throw new Error('No voice binary from ElevenLabs node');

const keys = JSON.parse(fs.readFileSync('/home/node/keys.json', 'utf8'));
const falApiKey = keys.falApiKey;
if (!falApiKey || falApiKey === 'YOUR_FAL_API_KEY') throw new Error('falApiKey not set in keys.json');

const tmpDir = '/tmp/n8n_music_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  const config = { falApiKey };
  fs.writeFileSync(path.join(tmpDir, 'cfg.json'), JSON.stringify(config));

  const js = [
    "const https = require('https');",
    "const fs = require('fs');",
    "const cfg = JSON.parse(fs.readFileSync(process.argv[2]+'/cfg.json','utf8'));",
    "const {falApiKey} = cfg;",
    "",
    "function dlFile(urlStr, dest) {",
    "  return new Promise((res, rej) => {",
    "    const u = new URL(urlStr);",
